UPDATE posts
SET state = #{state}
WHERE post_id = #{postId}
  AND state <> #{state}

UPDATE comments
SET state = #{state}
WHERE comment_id = #{commentId}
  AND state <> #{state}

mapper.select:
SELECT COUNT(*) > 0
FROM penalty_log
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND voided_at IS NULL

mapper.update:
UPDATE penalty_log
SET voided_at = NOW(),
    void_action_id = #{voidActionId}
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND voided_at IS NULL
